CREATE TABLE IF NOT EXISTS guild_config (
 guild_id BIGINT PRIMARY KEY, leaderboard_channel_id BIGINT, leaderboard_limit INTEGER NOT NULL DEFAULT 10 CHECK (leaderboard_limit BETWEEN 1 AND 100), rank_cooldown_seconds INTEGER NOT NULL DEFAULT 30 CHECK (rank_cooldown_seconds >= 0), debug_commands_enabled BOOLEAN NOT NULL DEFAULT FALSE, active_lobby_channel_id BIGINT, active_lobby_role_id BIGINT, website_moderator_role_id BIGINT, active_lobby_baseline_pending BOOLEAN NOT NULL DEFAULT TRUE, guide_forum_channel_id BIGINT, guide_notification_role_id BIGINT, guide_auto_delete_on_removal BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 1, updated_by BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS command_channel_rules (guild_id BIGINT NOT NULL REFERENCES guild_config(guild_id) ON DELETE CASCADE, command_name TEXT NOT NULL, channel_id BIGINT NOT NULL, allowed BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (guild_id, command_name, channel_id));
CREATE TABLE IF NOT EXISTS created_roles (guild_id BIGINT NOT NULL REFERENCES guild_config(guild_id) ON DELETE CASCADE, purpose TEXT NOT NULL, logical_name TEXT NOT NULL, role_id BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (guild_id,purpose,logical_name), UNIQUE (guild_id,role_id));
CREATE TABLE IF NOT EXISTS discord_publications (guild_id BIGINT NOT NULL REFERENCES guild_config(guild_id) ON DELETE CASCADE, feature TEXT NOT NULL, publication_key TEXT NOT NULL, channel_id BIGINT NOT NULL, message_id BIGINT, thread_id BIGINT, fingerprint TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (guild_id,feature,publication_key));
CREATE UNIQUE INDEX IF NOT EXISTS discord_publications_message_uq ON discord_publications(guild_id,channel_id,message_id) WHERE message_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS discord_publications_thread_uq ON discord_publications(guild_id,thread_id) WHERE thread_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS discord_publications_feature_idx ON discord_publications(guild_id,feature);
